import { ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION } from "./onboarding-constants";
import type { InnovationAttestCapture } from "./onboarding-types";

export function createEmptyInnovationAttestCapture(): InnovationAttestCapture {
  return {
    productDescription: "",
    applications: "",
    regulatoryGapArgumentation: "",
    regulatedProductGroup: "",
    technicalDescription: "",
    deviatingCharacteristics: "",
    executionRequirements: "",
    clientName: "",
    clientAddress: "",
    projectName: "",
    projectAddress: "",
    clientContactName: "",
    clientContactPhone: "",
    clientContactEmail: "",
    projectDescription: "",
    requestedPerformance: "",
    unacceptableRisks: "",
    clientConsent: "",
    attachments: [],
  };
}

const REQUIRED_TEXT_FIELDS = [
  "productDescription",
  "applications",
  "regulatoryGapArgumentation",
  "regulatedProductGroup",
  "technicalDescription",
  "clientName",
  "clientAddress",
  "projectName",
  "projectAddress",
  "clientContactName",
  "clientContactPhone",
  "clientContactEmail",
  "projectDescription",
  "requestedPerformance",
  "unacceptableRisks",
  "clientConsent",
] as const satisfies readonly (keyof InnovationAttestCapture)[];

/** Strikt: alle kern‑tekstvelden ingevuld; optionele blokken en bijlagen mogen leeg blijven (prototype). */
export function isInnovationAttestCaptureComplete(capture: InnovationAttestCapture): boolean {
  if (ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION) return true;
  return REQUIRED_TEXT_FIELDS.every((key) => capture[key].trim().length > 0);
}

export function normalizeInnovationAttestCapture(
  partial: Partial<InnovationAttestCapture> | undefined,
): InnovationAttestCapture {
  return {
    ...createEmptyInnovationAttestCapture(),
    ...partial,
    attachments: Array.isArray(partial?.attachments) ? partial.attachments : [],
  };
}

