import { registrationStepsSequenceForFlowState } from "../onboarding-registration-steps";
import type { OnboardingFlowState } from "../onboarding-types";
import type { OnboardingStep } from "../onboarding-types";

/** Snapshot fields updated when navigating between registration steps (Verder / stepper / Terug). */
export type StepCompletionNavigationFields = Pick<
  OnboardingFlowState,
  | "companyZetelStepCompleted"
  | "companyLegalEntitiesStepCompleted"
  | "invoicingStepCompleted"
  | "extrasStepCompleted"
  | "companyFieldHints"
  | "innovationAttestStepCompleted"
>;

/**
 * Derives persisted “stap bevestigd” flags after navigating from `activeStep` to `nextStep`.
 * Context‑only validators can worden `true` vóór **Verder**; deze vlaggen houden resume in lijn met de UI‑flow.
 */
export function stepCompletionStateAfterNavigation(
  prev: OnboardingFlowState,
  activeStep: OnboardingStep,
  nextStep: OnboardingStep,
): StepCompletionNavigationFields {
  const seq = registrationStepsSequenceForFlowState(prev);
  const fromIdx = seq.indexOf(activeStep);
  const toIdx = seq.indexOf(nextStep);
  const backward = toIdx < fromIdx;

  const companyIdx = seq.indexOf("company");
  const innovationIdx = seq.indexOf("innovationAttest");
  const legalIdx = seq.indexOf("companyLegalEntities");
  const invoicingIdx = seq.indexOf("invoicing");
  const extrasIdx = seq.indexOf("extras");

  let companyZetelStepCompleted = prev.companyZetelStepCompleted;
  let innovationAttestStepCompleted = prev.innovationAttestStepCompleted;
  let companyLegalEntitiesStepCompleted = prev.companyLegalEntitiesStepCompleted;
  let invoicingStepCompleted = prev.invoicingStepCompleted;
  let extrasStepCompleted = prev.extrasStepCompleted;
  let companyFieldHints = prev.companyFieldHints;

  if (toIdx <= companyIdx) {
    companyZetelStepCompleted = false;
    innovationAttestStepCompleted = false;
    companyLegalEntitiesStepCompleted = false;
    invoicingStepCompleted = false;
    extrasStepCompleted = false;
    if (nextStep === "company") {
      companyFieldHints = {};
    }
  } else if (backward) {
    if (innovationIdx >= 0 && toIdx <= innovationIdx) {
      innovationAttestStepCompleted = false;
      companyLegalEntitiesStepCompleted = false;
      invoicingStepCompleted = false;
      extrasStepCompleted = false;
    } else if (toIdx <= legalIdx) {
      companyLegalEntitiesStepCompleted = false;
      invoicingStepCompleted = false;
      extrasStepCompleted = false;
    } else if (toIdx <= invoicingIdx) {
      invoicingStepCompleted = false;
      extrasStepCompleted = false;
    } else if (toIdx <= extrasIdx) {
      extrasStepCompleted = false;
    }
  }

  if (
    activeStep === "company" &&
    (nextStep === "innovationAttest" || nextStep === "companyLegalEntities")
  ) {
    companyZetelStepCompleted = true;
  }
  if (activeStep === "innovationAttest" && nextStep === "companyLegalEntities") {
    innovationAttestStepCompleted = true;
  }
  if (activeStep === "companyLegalEntities" && nextStep === "invoicing") {
    companyLegalEntitiesStepCompleted = true;
  }
  if (activeStep === "invoicing" && nextStep === "extras") {
    invoicingStepCompleted = true;
  }
  if (activeStep === "invoicing" && nextStep === "summary") {
    invoicingStepCompleted = true;
    extrasStepCompleted = true;
  }
  if (activeStep === "extras" && nextStep === "summary") {
    extrasStepCompleted = true;
  }

  return {
    companyZetelStepCompleted,
    innovationAttestStepCompleted,
    companyLegalEntitiesStepCompleted,
    invoicingStepCompleted,
    extrasStepCompleted,
    companyFieldHints,
  };
}

import type { StepLayoutStep } from "@procertus-ui/ui";

import type {
  InnovationAttestCapture,
  OnboardingFlowState,
  CustomerContext,
  OnboardingStep,
} from "./onboarding-types";
import {
  formatRequesterStepperLabel,
  isApplicantLegalRepresentativeChoiceComplete,
  isLegalRepresentativeCaptureComplete,
  isOnboardingCompanyCoreStepValid,
  isOnboardingCompanyLegalEntitiesStepValid,
  isOnboardingCompanyZetelStepValid,
  isOnboardingInvoicingStepValid,
  isOnboardingOptionalContactsStepValid,
  isRegistrantCaptureValidForContext,
} from "./onboarding-flow-helpers";
import { isInnovationAttestCaptureComplete } from "./onboarding-innovation-attest";
import { registrationDraftsIncludeInnovationAttest, registrationStepsSequence } from "./onboarding-registration-steps";
import { isRegistrationIdentifierValidForOrigin } from "./lib/registration-identifier-for-origin";
import { isVatIdentifierPlausible } from "./lib/vatPrototypePresets";
import { ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION } from "./onboarding-constants";

export type OnboardingPhaseValidity = {
  registrationStepOk: boolean;
  /** Maatschappelijke zetel (naam + adres). */
  companyZetelOk: boolean;
  /** Juridisch aanspreekpunt / vestigingen per aanvraag. */
  companyLegalEntitiesOk: boolean;
  companyCoreOk: boolean;
  invoicingStepOk: boolean;
  optionalContactsOk: boolean;
  /** Innovatie‑attest blok afgerond (of niet van toepassing). */
  innovationAttestOk: boolean;
  summaryStepOk: boolean;
};

export type DeriveOnboardingPhaseValidityInput = {
  requestOrigin: OnboardingFlowState["requestOrigin"];
  context: CustomerContext;
  drafts: readonly OnboardingFlowState["drafts"];
  certificationInquiryDraftIds: readonly string[];
  innovationAttestCapture: InnovationAttestCapture;
  innovationAttestStepCompleted: boolean;
};

/** @param requestOrigin Flow `requestOrigin`; `""` treated as unset. */
export function deriveOnboardingPhaseValidityForFlow(
  input: DeriveOnboardingPhaseValidityInput,
): OnboardingPhaseValidity & { hasCustomerContext: boolean } {
  const {
    requestOrigin,
    context,
    drafts,
    certificationInquiryDraftIds,
    innovationAttestCapture,
    innovationAttestStepCompleted,
  } = input;

  const legalRepChoiceOk = isApplicantLegalRepresentativeChoiceComplete(context);
  const registrationBodyComplete =
    isRegistrantCaptureValidForContext(context) &&
    isLegalRepresentativeCaptureComplete(context) &&
    (requestOrigin
      ? isRegistrationIdentifierValidForOrigin(context.vatNumber ?? "", requestOrigin)
      : isVatIdentifierPlausible(context.vatNumber ?? ""));
  const hasCustomerContext = legalRepChoiceOk && registrationBodyComplete;
  const registrationStepOk =
    legalRepChoiceOk &&
    (registrationBodyComplete || ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION);
  const companyZetelOk =
    isOnboardingCompanyZetelStepValid(context) || ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION;
  /** Strict: alle aanvragen moeten gekoppeld zijn voor verder naar facturatie. */
  const companyLegalEntitiesOk = isOnboardingCompanyLegalEntitiesStepValid(
    context,
    certificationInquiryDraftIds,
  );
  const companyCoreOk = isOnboardingCompanyCoreStepValid(context, certificationInquiryDraftIds);
  const invoicingStepOk =
    isOnboardingInvoicingStepValid(context, certificationInquiryDraftIds) ||
    ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION;
  const optionalContactsOk =
    isOnboardingOptionalContactsStepValid(context) || ONBOARDING_PROTOTYPE_RELAX_STEP_VALIDATION;

  const needsInnovationAttest = registrationDraftsIncludeInnovationAttest(
    drafts,
    certificationInquiryDraftIds,
  );
  const innovationAttestOk =
    !needsInnovationAttest ||
    (isInnovationAttestCaptureComplete(innovationAttestCapture) && innovationAttestStepCompleted);

  const summaryStepOk =
    companyCoreOk && invoicingStepOk && optionalContactsOk && innovationAttestOk;

  return {
    hasCustomerContext,
    registrationStepOk,
    companyZetelOk,
    companyLegalEntitiesOk,
    companyCoreOk,
    invoicingStepOk,
    optionalContactsOk,
    innovationAttestOk,
    summaryStepOk,
  };
}

export type BuildOnboardingStepperStepsInput = {
  drafts: OnboardingFlowState["drafts"];
  requestOrigin: OnboardingFlowState["requestOrigin"];
  context: CustomerContext;
  certificationInquiryDraftIds: readonly string[];
  innovationAttestCapture: InnovationAttestCapture;
  innovationAttestStepCompleted: boolean;
};

export function buildOnboardingStepperSteps(
  input: BuildOnboardingStepperStepsInput,
): StepLayoutStep[] {
  const {
    drafts,
    requestOrigin,
    context,
    certificationInquiryDraftIds,
    innovationAttestCapture,
    innovationAttestStepCompleted,
  } = input;

  const hasDrafts = drafts.length > 0;
  const legalRepChoiceOk = isApplicantLegalRepresentativeChoiceComplete(context);
  const needsInnovationAttest = registrationDraftsIncludeInnovationAttest(
    drafts,
    certificationInquiryDraftIds,
  );

  const {
    registrationStepOk,
    companyZetelOk,
    companyCoreOk,
    invoicingStepOk,
    summaryStepOk,
    innovationAttestOk,
  } = deriveOnboardingPhaseValidityForFlow({
    requestOrigin,
    context,
    drafts,
    certificationInquiryDraftIds,
    innovationAttestCapture,
    innovationAttestStepCompleted,
  });

  const companyStepOk = companyCoreOk;
  const extrasAvailabilityDepsOk =
    legalRepChoiceOk &&
    registrationStepOk &&
    companyCoreOk &&
    invoicingStepOk &&
    innovationAttestOk;

  const seq = registrationStepsSequence(drafts, certificationInquiryDraftIds);

  const innovationStepAvailable =
    hasDrafts &&
    requestOrigin !== "" &&
    legalRepChoiceOk &&
    registrationStepOk &&
    companyZetelOk &&
    needsInnovationAttest;

  const legalEntitiesAvailable =
    hasDrafts &&
    requestOrigin !== "" &&
    legalRepChoiceOk &&
    registrationStepOk &&
    companyZetelOk &&
    (!needsInnovationAttest || innovationAttestStepCompleted);

  const stepLayouts: Record<OnboardingStep, StepLayoutStep> = {
    origin: {
      id: "origin",
      title: "Land of regio",
      description:
        requestOrigin === ""
          ? "Waar is uw bedrijf?"
          : ({
              be: "België",
              nl: "Nederland",
              eu: "Europa (EU)",
              us: "Verenigde Staten",
              other: "Anders",
            }[requestOrigin] ?? ""),
      available: hasDrafts,
    },
    customer: {
      id: "customer",
      title: "Registratie",
      description: formatRequesterStepperLabel(context),
      available: hasDrafts && requestOrigin !== "",
    },
    company: {
      id: "company",
      title: "Maatschappelijke zetel",
      description:
        context.organizationName.trim() || "Officiële gegevens van de hoofdrechtspersoon",
      available: hasDrafts && requestOrigin !== "" && legalRepChoiceOk && registrationStepOk,
    },
    innovationAttest: {
      id: "innovationAttest",
      title: "Innovatie-attest",
      description: "Innovatief product en project",
      available: innovationStepAvailable,
    },
    companyLegalEntities: {
      id: "companyLegalEntities",
      title: "Certificatie (entiteit)",
      description:
        context.headOfficeIsCertificationLegalEntity === ""
          ? "Zetel of vestigingen per aanvraag"
          : context.headOfficeIsCertificationLegalEntity === "yes"
            ? "Zetel voor alle aanvragen in dit dossier"
            : "Vestiging per aanvraag",
      available: legalEntitiesAvailable,
    },
    invoicing: {
      id: "invoicing",
      title: "Facturatie",
      description:
        context.invoicingEmail.trim() ||
        (context.invoicingMirrorCertificationLegalEntities
          ? "Zelfde rechts‑persoon als bij certificatie"
          : "Factuur‑rechtspersoon per aanvraag"),
      available:
        hasDrafts &&
        requestOrigin !== "" &&
        legalRepChoiceOk &&
        registrationStepOk &&
        companyStepOk,
    },
    extras: {
      id: "extras",
      title: "Extra contacten",
      description: "Certificatie- en reservecontact (optioneel)",
      available: hasDrafts && requestOrigin !== "" && extrasAvailabilityDepsOk,
    },
    summary: {
      id: "summary",
      title: "Nazicht",
      description: "Gegevens en aanvragen nakijken",
      available:
        hasDrafts &&
        requestOrigin !== "" &&
        legalRepChoiceOk &&
        registrationStepOk &&
        summaryStepOk,
    },
  };

  return seq.map((id) => stepLayouts[id]);
}

