import { Cancel01Icon, Upload01Icon } from "@hugeicons/core-free-icons";
import { HugeiconsIcon } from "@hugeicons/react";
import {
  Button,
  Field,
  FieldContent,
  FieldLabel,
  Input,
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemGroup,
  ItemTitle,
  Textarea,
} from "@procertus-ui/ui";
import { useCallback, useId, useRef } from "react";

import { useOnboardingFlowContext } from "../../../onboarding/onboarding-flow-provider";
import type { InnovationAttestCapture } from "../../../onboarding/onboarding-types";

function FormTextarea({
  id,
  label,
  value,
  onChange,
  minRows = 4,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (next: string) => void;
  minRows?: number;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <FieldContent>
        <Textarea
          id={id}
          value={value}
          rows={minRows}
          onChange={(e) => onChange(e.target.value)}
          className="min-h-[5.5rem] resize-y"
        />
      </FieldContent>
    </Field>
  );
}

function FormInput({
  id,
  label,
  value,
  onChange,
}: {
  id: string;
  label: string;
  value: string;
  onChange: (next: string) => void;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <FieldContent>
        <Input id={id} type="text" value={value} onChange={(e) => onChange(e.target.value)} />
      </FieldContent>
    </Field>
  );
}

export function OnboardingInnovationAttestStep() {
  const baseId = useId();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { flowState, setFlowState } = useOnboardingFlowContext();
  const capture = flowState.innovationAttestCapture;

  const patchCapture = useCallback(
    (patch: Partial<InnovationAttestCapture>) => {
      setFlowState((prev) => ({
        ...prev,
        innovationAttestCapture: { ...prev.innovationAttestCapture, ...patch },
      }));
    },
    [setFlowState],
  );

  const handleMockFiles = useCallback(
    (list: FileList | null) => {
      if (!list?.length) return;
      const added = Array.from(list).map((file, index) => ({
        id: `mock-${Date.now()}-${index}-${Math.random().toString(36).slice(2, 9)}`,
        name: file.name,
        sizeLabel: `${Math.max(1, Math.round(file.size / 1024))} KB`,
      }));
      patchCapture({
        attachments: [...capture.attachments, ...added],
      });
      if (fileInputRef.current) fileInputRef.current.value = "";
    },
    [capture.attachments, patchCapture],
  );

  const removeAttachment = useCallback(
    (id: string) => {
      patchCapture({
        attachments: capture.attachments.filter((a) => a.id !== id),
      });
    },
    [capture.attachments, patchCapture],
  );

  const pid = (suffix: string) => `${baseId}-${suffix}`;

  return (
    <div className="space-y-6">
      <div className="space-y-4">
        <div className="space-y-1">
          <h3 className="text-sm font-semibold tracking-tight text-foreground">Innovatief product</h3>
        </div>
        <div className="grid gap-4">
          <FormTextarea
            id={pid("prod-desc")}
            label="Beschrijving van het innovatieve product"
            value={capture.productDescription}
            onChange={(v) => patchCapture({ productDescription: v })}
          />
          <FormTextarea
            id={pid("applications")}
            label="Toepassing(en)"
            value={capture.applications}
            onChange={(v) => patchCapture({ applications: v })}
          />
          <FormTextarea
            id={pid("gap")}
            label="Argumentatie waarom het innovatieve product niet onder de bestaande voorschriften (normen, PTV, standaardbestekken…) kan vallen"
            value={capture.regulatoryGapArgumentation}
            onChange={(v) => patchCapture({ regulatoryGapArgumentation: v })}
          />
          <FormTextarea
            id={pid("group")}
            label="Opgave van de gereglementeerde productgroep waarbij het innovatieve product het meest aansluit voor toepassing in het geselecteerde project"
            value={capture.regulatedProductGroup}
            onChange={(v) => patchCapture({ regulatedProductGroup: v })}
          />
          <FormTextarea
            id={pid("tech")}
            label="Technische beschrijving van het product (incl. grondstoffen, samenstelling, dimensies …)"
            value={capture.technicalDescription}
            onChange={(v) => patchCapture({ technicalDescription: v })}
          />
          <FormTextarea
            id={pid("deviate")}
            label="Indien van toepassing: Specifieke kenmerken van het product, afwijkend van deze van de gereglementeerde productgroep"
            value={capture.deviatingCharacteristics}
            onChange={(v) => patchCapture({ deviatingCharacteristics: v })}
          />
          <FormTextarea
            id={pid("exec")}
            label="Indien van toepassing: Specifieke uitvoerings- of nabehandelingseisen gelinkt aan het gebruik van het product"
            value={capture.executionRequirements}
            onChange={(v) => patchCapture({ executionRequirements: v })}
          />
        </div>
      </div>

      <div className="space-y-4">
        <div className="space-y-1">
          <h3 className="text-sm font-semibold tracking-tight text-foreground">Bewijsvoering</h3>
          <p className="text-xs leading-relaxed text-muted-foreground">
            Bestaande bewijsvoering van het innovatief product dient te worden toegevoegd aan de
            aanvraag:
          </p>
        </div>
        <ul className="list-disc space-y-1 pl-5 text-xs leading-relaxed text-muted-foreground">
          <li>
            Samenvattende overzichtstabel van de uitgevoerde of lopende proeven, de uitvoerder, de
            proefmethode, desgevallend de proefresultaten die de technische beschrijving van het
            product onderbouwen
          </li>
          <li>Proefverslagen opgesteld door onderzoeksinstellingen</li>
          <li>Beschrijvingen van reeds eerder uitgevoerde pilootprojecten</li>
        </ul>

        <input
          ref={fileInputRef}
          type="file"
          multiple
          className="sr-only"
          aria-hidden
          tabIndex={-1}
          onChange={(e) => handleMockFiles(e.target.files)}
        />
        <Button type="button" variant="outline" className="gap-2" onClick={() => fileInputRef.current?.click()}>
          <HugeiconsIcon icon={Upload01Icon} className="size-4" strokeWidth={1.5} />
          Bestanden toevoegen
        </Button>
        <p className="text-xs text-muted-foreground">
          Meerdere documenten mogelijk — dit is een prototype zonder echte opslag.
        </p>

        {capture.attachments.length > 0 ? (
          <ItemGroup className="gap-2">
            {capture.attachments.map((file) => (
              <Item key={file.id} variant="outline" className="bg-card py-2">
                <ItemContent>
                  <ItemTitle className="text-sm">{file.name}</ItemTitle>
                  <ItemDescription>{file.sizeLabel}</ItemDescription>
                </ItemContent>
                <ItemActions>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    aria-label={`Verwijder ${file.name}`}
                    onClick={() => removeAttachment(file.id)}
                  >
                    <HugeiconsIcon icon={Cancel01Icon} className="size-4" strokeWidth={1.5} />
                  </Button>
                </ItemActions>
              </Item>
            ))}
          </ItemGroup>
        ) : null}
      </div>

      <div className="space-y-4">
        <div className="space-y-1">
          <h3 className="text-sm font-semibold tracking-tight text-foreground">
            Project om het innovatief product toe te passen
          </h3>
        </div>
        <div className="grid gap-4 md:grid-cols-2">
          <FormInput
            id={pid("client")}
            label="Bouwheer"
            value={capture.clientName}
            onChange={(v) => patchCapture({ clientName: v })}
          />
          <FormInput
            id={pid("client-addr")}
            label="Adres bouwheer"
            value={capture.clientAddress}
            onChange={(v) => patchCapture({ clientAddress: v })}
          />
          <FormInput
            id={pid("proj-name")}
            label="Naam project"
            value={capture.projectName}
            onChange={(v) => patchCapture({ projectName: v })}
          />
          <FormInput
            id={pid("proj-addr")}
            label="Adres project"
            value={capture.projectAddress}
            onChange={(v) => patchCapture({ projectAddress: v })}
          />
          <FormInput
            id={pid("contact")}
            label="Contactpersoon voor de bouwheer in het kader van het project"
            value={capture.clientContactName}
            onChange={(v) => patchCapture({ clientContactName: v })}
          />
          <FormInput
            id={pid("phone")}
            label="Telefoonnummer van deze contactpersoon"
            value={capture.clientContactPhone}
            onChange={(v) => patchCapture({ clientContactPhone: v })}
          />
          <div className="md:col-span-2">
            <FormInput
              id={pid("email")}
              label="E-mail van deze contactpersoon"
              value={capture.clientContactEmail}
              onChange={(v) => patchCapture({ clientContactEmail: v })}
            />
          </div>
        </div>
        <FormTextarea
          id={pid("proj-desc")}
          label="Beschrijving van het project (toepassing, volumes, afmetingen, uitvoeringsperiode, gewenste levensduur, specifieke elementen…)"
          value={capture.projectDescription}
          onChange={(v) => patchCapture({ projectDescription: v })}
          minRows={5}
        />
        <FormTextarea
          id={pid("performance")}
