function FormTextarea({
  id,
  label,
  description,
  value,
  onChange,
  minRows = 4,
}: {
  id: string;
  label: string;
  description: string;
  value: string;
  onChange: (next: string) => void;
  minRows?: number;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
      <FieldContent>
        <Textarea
          id={id}
          value={value}
          rows={minRows}
          onChange={(e) => onChange(e.target.value)}
          className="min-h-22 resize-y"
          aria-describedby={`${id}-desc`}
        />
        <FieldDescription id={`${id}-desc`}>{description}</FieldDescription>
      </FieldContent>
    </Field>
  );
}

function FormInput({
  id,
  label,
  description,
  value,
  onChange,
}: {
  id: string;
  label: string;
  description: string;
  value: string;
  onChange: (next: string) => void;
}) {
  return (
    <Field>
      <FieldLabel htmlFor={id}>{label}</FieldLabel>
