  value,
  onChange,
  minRows = 4,
  required = false,
}: {
  id: string;
  label: string;
  description: string;
  value: string;
  onChange: (next: string) => void;
  minRows?: number;
  required?: boolean;
}) {
  return (
    <Field data-required={required ? "" : undefined}>
      <FieldLabel htmlFor={id}>
        {label}
        {required ? (
          <span className="text-destructive" aria-hidden>
            {" "}
            *
